#!/usr/bin/env python3
"""Bind the independent GFI1--GFI17 mathematical review to frozen bytes."""
from pathlib import Path
import argparse, hashlib, json, subprocess
ap=argparse.ArgumentParser(description=__doc__)
ap.add_argument('--workspace', type=Path, default=Path(__file__).resolve().parents[3])
ap.add_argument('--main-sha', required=True)
ap.add_argument('--output', type=Path, required=True)
a=ap.parse_args();root=a.workspace.resolve();comp=root/'work_v035/global_final_installation';src=root/'lean_source';base=root/'reconstruction_v034';out=a.output.resolve();out.mkdir(parents=True,exist_ok=True)
sha=lambda b:hashlib.sha256(b).hexdigest()
p=json.loads((comp/'provenance.json').read_text());raw=(comp/'main.tex').read_bytes();lines=raw.splitlines(keepends=True)
assert sha(raw)==a.main_sha==p['main_sha256']
assert p['source_commit']=='7cbf7a0c32fca1badf05931879a37c3f8a2b03b4'
pin=p['source_commit'];old={c['id']for c in json.loads((base/'provenance.json').read_text())['claims']};loss={c['id']for c in json.loads((root/'work_v035/global_loss/provenance.json').read_text())['claims']};ids={c['id']for c in p['claims']}
assert ids=={f'GFI{i}'for i in range(1,18)}
cache={};ranges=set();refs=0;blocks=[]
for c in p['claims']:
    assert set(c['depends_on'])<=old|loss|ids
    q=c['proof_location'];b=b''.join(lines[q['line_start']-1:q['line_end']]);assert sha(b)==q['range_sha256']==q['sha256'];assert q['file_sha256']==sha(raw)
    blocks.append(dict(id=c['id'],sha256=sha(b),line_start=q['line_start'],line_end=q['line_end']))
    for s in c['sources']:
        f=s['path'];b=cache.setdefault(f,(src/f).read_bytes());ll=b.splitlines(keepends=True);r=b''.join(ll[s['line_start']-1:s['line_end']])
        assert sha(b)==s['sha256']==s['file_sha256'];assert sha(r)==s['range_sha256'];refs+=1;ranges.add((f,s['line_start'],s['line_end']))
for f,b in cache.items():assert b==subprocess.check_output(['git','show',pin+':'+f],cwd=src)
for t in p['inherited_proof_inputs']:
    f=(root/'work_v035'/t['file']) if t['file']=='global_loss/provenance.json' else (base/t['file'])
    assert sha(f.read_bytes())==t['sha256'],t['file']
checks=[
(['GFI1'],'The original rank and Scale equalities, fixed host q,d,QS, root discriminant, g and CGam give every common scalar. The separate eta_eq field is now explicitly used for etaSz. Equality on natural representatives of every residue unit proves equality of the original reciprocity homomorphisms; the required two-sign interchange is retained when constructing arithOf. No new arithmetic model is chosen.'),
(['GFI2'],'The LossFS witnesses include one actually realizing i1. The original coverS applied to that member supplies every base-point member, and the exact common top-label image identifies a matching original top. Consequently all pt(h) carry the same av,bv. This is a finite choice of base-point members and does not use CoverAll or realization of arbitrary admissible weights.'),
(['GFI3'],'The val/ofNat inverses give the exact top equivalence; the source range 4 Lw s<n0 puts all second-set entries in the injectivity range of dig. The place map is injective and has the same finite cardinality as Phi. The definition of w uses its unique representative and retains the original off-image value 1. Both lift and place reindexings preserve multiplicity.'),
(['GFI4'],'Every scalar and functional field of the original Data record was compared with the literal Mod.data definition. The same words, ranks, source/quotient lattices, rational maps and support are used. Ga and Ta retain squared-metric size normalization; IO has exactly one normalized logarithmic-place/ramification factor. TiePts, TieGlobal and TieLocal follow on these objects.'),
(['GFI5'],'CharF is used once at the common base index and arithmetic record. The resulting single character functional satisfies the exact primitive-character identity and real quadratic value. Nodes gives w>=1 on precisely Phi; actual top windows give a<=at<=2a and the near-x clause. The natural cutoff ceil(2a) therefore satisfies every j,t,rho inequality. All five Reads clauses and the required heterogeneous arithmetic equality are checked before applying loss.'),
(['GFI6'],'All numerical constants and thresholds are extracted before x and any member. The common constant K=max(Cd,0)+Cc+Cs+C1+Cl+6 bounds every coefficient. The frame envelope etaBar,eBar is chosen at x before any member-specific errors. All seventeen HidaSetting clauses have the correct positivity, rank, level-prime, slope and error meanings. The comparison coefficient cH is distinguished from the fixed height exponent CH.'),
(['GFI7'],'The actual LinkDIV inequalities transport through the unchanged common scalar and top sums. All factors multiplying Cd are nonnegative, so max(Cd,0) is a valid enlargement. Triangle inequality over precisely m lifts gives EComp5 with m B0. The logarithmic Omega term, word heights and type-prime logarithms agree exactly, yielding DIV and HComp without a normalization shift.'),
(['GFI8'],'Count_at becomes all three Count5 fields under the original bijective lift/place reindexings, retaining 1/f. The ordinary source slope bounds become Slopes on the same lattice. The support and lift sum give equality of Ee, and the quotient lower loss retains C1 IO+C1 nT m(a/k+bprime)logT+C1 Xpp+1. Thus the literal QuotientSlopeBoundsWith is supplied, including its additive 1.'),
(['GFI9'],'Each base-point member realizes the original pair and therefore satisfies both Loss_at clauses with the same constant. The actual common arithmetic reading and cutoff satisfy GFI5, so the universal second loss clause applies to the ledger ASK. The first clause identifies the exact IO. Both inequalities have precisely LoP and hold simultaneously for every base point.'),
(['GFI10'],'The weighted rank mean and maximum excess are the original sFrame and uFrame. FrameF applies for every permitted height, hence at HH=x^CH b. LinkDIV and the actual algebraic-dual identity give the required s-muMinCC<=HH. HHBound is then exact. LinkIRR and the same frame envelopes give all six FParams inequalities for the same retained target and rational maps.'),
(['GFI11'],'The positive chosen top-density lower bound gives nT>=1. Every ErrWindows0 field was checked against the literal definition, including word cardinality, the k upper exponent, the nonnegative budgets, delBar<=1/2 and coefficient bounds. The full extra error-budget inequality follows from the original factor 6 and K>=6, with no use of the weaker ErrWindowsWeak interface.'),
(['GFI12'],'Both BNBounds are equalities after the actual top and second-set cardinality transport. NodeSizes, common cutoff, bprime Xprime=xb and signs give every GrowthInequalitySizes field. The single character record converts the supplied original thin and quadratic bounds to the exact ThinScales and ValuesAtX. CostWindows and all five RestSize clauses retain their original constants and exponents.'),
(['GFI13'],'All existential objects of ChainTied are explicitly fixed and the four ties, five scalar/constant conditions, Ident, eleven ledger predicates, ErrWindows, BNBounds, remaining growth, cost and RestSize are accounted for. Constants precede x; the realized degree pair and permitted error witnesses may depend on x. The same family is used throughout.'),
(['GFI14'],'The direct density proof is valid: after division by n=o n0, the inverse lower-density logarithm is bounded by log O+2loglog x+C sqrt((9/2)log x loglog x)=o(log x), uniformly in the original member. The coarse harmonic prime sum is at most 8(log Xprime)^2; using delta1 n<=2nT gives 64 Cb nT x^(-2+2epsilon/3), absorbed into the literal ChosenBadp bound. ChosenWall supplies the same realized pair directly from an existing index and its original windows. The entire named Seven packet is obtained without CoverAll.'),
(['GFI15'],'The generic eleven-field consumer is now justified without silently assuming the stronger second-layer construction. A supplied FreeT decomposes into regular finite diamond orbits; tensor coordinate-sum kernels give exactly r(T-2)^f versus r(T-1)^f dimensions. Supplied hMu is the mean identity. Proviso and the setting give positive full and ramified rank, and the original saturated intersection gives maximal-slope monotonicity. The original hI,hR,hB feed the finite-DVR/ordered-product argument and RSL11 fullness. GVC/GFA and the supplied links produce the remaining exact numerical fields; LFS17 supplies both losses. The stronger unused PartFiveFamilyBounds is not asserted.'),
(['GFI16'],'The positive epsilon cutoffs are joined by a finite minimum and the TransportedAlt bounds by the exact componentwise supremum before the family and CH. Original Large monotonicity recovers each input for the same lists and family. Joining the fixed tuple with mid=1 forces CH>=1 because CH is literally in cMid. Later x thresholds are permitted to depend on that supplied family and its inputs, but precede every member and word.'),
(['GFI17'],'GLS13 supplies the same-class eleven-field packet from original Duty and the compatible second layer. D3 membership and Duty project to the very same family ChosenWall. The complete conditional Closed consumer has constants Cabs=2,C0=3,column constant4,eD=2,eL=0. ZW then retains exponent 1/2+9epsilon. No geometric, arithmetic, spectral, retained-defect, denominator, compatible-selector or family-existence producer is inferred.')]
rows=[dict(id=f'GFI-REV-{i:02}',claims=cs,result='PASS',finding=s)for i,(cs,s)in enumerate(checks,1)]
report=dict(schema='rh-independent-proof-review/1',artifact_version='0.35',reviewer='/root/audit_global_routes',date='2026-11-22',component='global_final_installation',status='PASS',verdict='PASS',scope='Independent complete mathematical and exact-source review of GFI1--GFI17, conditional on their stated original family and exact inherited predicates. The pinned formal proof is assumed correct.',source_commit=pin,claims_reviewed=[f'GFI{i}'for i in range(1,18)],proof_file='global_final_installation/main.tex',provenance_file='global_final_installation/provenance.json',closure_file='global_final_installation/closure.json',proof_file_sha256=sha(raw),main_sha256=sha(raw),provenance_file_sha256=sha((comp/'provenance.json').read_bytes()),closure_file_sha256=sha((comp/'closure.json').read_bytes()),proof_blocks=blocks,source_validation=dict(claim_source_ranges_checked=refs,distinct_source_ranges_checked=len(ranges),pinned_files_checked=len(cache),all_ranges_and_blobs_match=True,all_proof_block_hashes_match=True,inherited_input_hashes_checked=len(p['inherited_proof_inputs']),all_inherited_input_hashes_match=True),checks=rows,resolved_issues=[dict(id='GFI-GENERIC-PACKET-SCOPE',claims=['GFI15','GFI16'],resolution='Added a complete finite-orbit tensor-kernel argument and direct hMu/maximal-slope/positive-rank installation from the eleven fields, removing reliance on the stronger actual-forms producer in the generic consumer.'),dict(id='GFI-ETA-DICTIONARY',claims=['GFI1','GFI4','GFI12'],resolution='The separate original eta_eq field explicitly supplies etaSz equality; it is not inferred from x,epsilon,J alone.')],required_corrections=[],retained_hypotheses=['Compatible common family and original Duty/second-layer producer for the selected class.','Original LinkG, LinkS, LinkIRR, LinkDIV, LinkMu and chosen data in the exact consumer antecedents.','Other upstream rank, theta, arithmetic and cohomological producer obligations in the whole-proof audit.'],limitations=['No Lean compilation or independent kernel replay is performed.','Inherited results are used in their recorded scope and their relevant applications are checked; source and proof hashes do not replace mathematical review.','LFS17 is the same-version loss input, whose author is this reviewer; its separate independent numerical/source review is by /root/audit_count_path.','A complete human RH or unrestricted Dirichlet-GRH proof is not asserted.'])
(out/'global_final_installation_review.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
txt='GFI1--GFI17: INDEPENDENT MATHEMATICAL AND EXACT-SOURCE REVIEW\n\nVerdict: PASS.\nSource pin: '+pin+'\nProof SHA256: '+report['main_sha256']+'\nProvenance SHA256: '+report['provenance_file_sha256']+'\nClosure SHA256: '+report['closure_file_sha256']+'\n\n'
txt+='All 17 human proof blocks, '+str(refs)+' claim/source references, '+str(len(ranges))+' distinct source ranges in '+str(len(cache))+' pinned files, and '+str(len(p['inherited_proof_inputs']))+' inherited file hashes were independently checked.\n\n'
for row in rows:txt+=', '.join(row['claims'])+' — PASS\n'+row['finding']+'\n\n'
txt+='Resolved findings: explicit generic FreeT-to-ramified packet proof and the literal eta_eq dictionary. No required correction remains.\n\n'
txt+='This closes the original conditional global assembly consumer only. The common family, compatible selector, duties and all stated arithmetic/spectral/retained-defect/local-gain inputs retain their original scope. No full human RH/GRH proof or Lean replay is claimed.\n'
