print(json.dumps(dict(status='PASS',main_sha256=sha(raw),review_json_sha256=sha((out/'global_final_installation_review.json').read_bytes()),review_txt_sha256=sha((out/'global_final_installation_review.txt').read_bytes()),source_references=refs,source_files=len(cache)),indent=2))
